const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '植物细胞结构示意图' },
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '细胞核' },
      { kind: 'text', payload: '液泡' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var m = Math.min(W, H);

    function rr(x0, y0, x1, y1, r) {
      r = Math.max(0, Math.min(r, Math.min(x1 - x0, y1 - y0) / 2));
      var k = r * 0.5522847498;
      return [
        ['M', x0 + r, y0],
        ['L', x1 - r, y0],
        ['C', x1 - r + k, y0, x1, y0 + r - k, x1, y0 + r],
        ['L', x1, y1 - r],
        ['C', x1, y1 - r + k, x1 - r + k, y1, x1 - r, y1],
        ['L', x0 + r, y1],
        ['C', x0 + r - k, y1, x0, y1 - r + k, x0, y1 - r],
        ['L', x0, y0 + r],
        ['C', x0, y0 + r - k, x0 + r - k, y0, x0 + r, y0],
        ['Z']
      ];
    }

    function ell(cx, cy, rx, ry) {
      var kx = rx * 0.5522847498;
      var ky = ry * 0.5522847498;
      return [
        ['M', cx + rx, cy],
        ['C', cx + rx, cy + ky, cx + kx, cy + ry, cx, cy + ry],
        ['C', cx - kx, cy + ry, cx - rx, cy + ky, cx - rx, cy],
        ['C', cx - rx, cy - ky, cx - kx, cy - ry, cx, cy - ry],
        ['C', cx + kx, cy - ry, cx + rx, cy - ky, cx + rx, cy],
        ['Z']
      ];
    }

    function seg(x1, y1, x2, y2) {
      return [['M', x1, y1], ['L', x2, y2]];
    }

    var x0 = W * 0.12, x1 = W * 0.88;
    var y0 = H * 0.17, y1 = H * 0.94;
    var r = m * 0.09;
    var t = Math.max(6, m * 0.018);

    var vcx = W * 0.46, vcy = H * 0.62, vrx = W * 0.25, vry = H * 0.21;
    var ncx = W * 0.73, ncy = H * 0.33, nr = m * 0.075;

    var bg = [['M', 0, 0], ['L', W, 0], ['L', W, H], ['L', 0, H], ['Z']];

    var paths = [
      { id: 'bg', commands: bg },
      { id: 'wallEdge', commands: rr(x0 - 2, y0 - 2, x1 + 2, y1 + 2, r + 2) },
      { id: 'wall', commands: rr(x0, y0, x1, y1, r) },
      { id: 'cellEdge', commands: rr(x0 + t - 1.2, y0 + t - 1.2, x1 - t + 1.2, y1 - t + 1.2, Math.max(2, r - t + 1.2)) },
      { id: 'cell', commands: rr(x0 + t, y0 + t, x1 - t, y1 - t, Math.max(2, r - t)) },
      { id: 'vacEdge', commands: ell(vcx, vcy, vrx + 1.6, vry + 1.6) },
      { id: 'vac', commands: ell(vcx, vcy, vrx, vry) },
      { id: 'nucEdge', commands: ell(ncx, ncy, nr + 1.6, nr + 1.6) },
      { id: 'nuc', commands: ell(ncx, ncy, nr, nr) },
      { id: 'leadWall', commands: seg(W * 0.225, H * 0.23, x0 + t * 0.5, H * 0.23) },
      { id: 'leadNuc', commands: seg(ncx - nr - 12, ncy, ncx - nr + 1, ncy) },
      { id: 'dotWall', commands: ell(x0 + t * 0.5, H * 0.23, 2.4, 2.4) },
      { id: 'dotNuc', commands: ell(ncx - nr + 1, ncy, 2.4, 2.4) }
    ];

    return {
      schemaVersion: 1,
      sceneId: 'plant-cell-diagram',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'bg', fill: '#FBFDF6' },
          { type: 'path', pathId: 'wallEdge', fill: '#5E7F3E' },
          { type: 'path', pathId: 'wall', fill: '#C6DB9B' },
          { type: 'path', pathId: 'cellEdge', fill: '#7E9E5C' },
          { type: 'path', pathId: 'cell', fill: '#F5FAEA' },
          { type: 'path', pathId: 'vacEdge', fill: '#6FA5C6' },
          { type: 'path', pathId: 'vac', fill: '#CDE6F2' },
          { type: 'path', pathId: 'nucEdge', fill: '#8D6BA6' },
          { type: 'path', pathId: 'nuc', fill: '#DCC4E8' },
          { type: 'path', pathId: 'leadWall', fill: '#4A5B3A', stroke: { width: 1.2 } },
          { type: 'path', pathId: 'leadNuc', fill: '#4A5B3A', stroke: { width: 1.2 } },
          { type: 'path', pathId: 'dotWall', fill: '#4A5B3A' },
          { type: 'path', pathId: 'dotNuc', fill: '#4A5B3A' },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: W * 0.5, y: H * 0.045 }, hAlign: 'center', vAlign: 'top', color: '#2F3D22' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: W * 0.235, y: H * 0.23 }, hAlign: 'left', vAlign: 'middle', color: '#2F3D22' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: ncx - nr - 14, y: ncy }, hAlign: 'right', vAlign: 'middle', color: '#2F3D22' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: vcx, y: vcy }, hAlign: 'center', vAlign: 'middle', color: '#1F4459' }
        ]
      }
    };
  }
};
